from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # The full line is a barrier. Move the figure against it and draw an 8
    # stripe immediately beyond the figure, away from the barrier.
    divider_row = next((r for r, row in enumerate(grid)
                        if row[0] != bg and all(v == row[0] for v in row)), None)
    if divider_row is not None:
        divider = grid[divider_row][0]
        pts = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if r != divider_row and grid[r][c] != bg and grid[r][c] != divider]
        if not pts:
            return out
        top = min(r for r, c, v in pts)
        bottom = max(r for r, c, v in pts)
        for r, c, v in pts:
            out[r][c] = bg
        shift = divider_row + 1 - top
        for r, c, v in pts:
            out[r + shift][c] = v
        stripe_row = divider_row + 1 + (bottom - top) + 1
        if stripe_row < h:
            out[stripe_row] = [8] * w
        return out

    divider_col = next((c for c in range(w)
                        if grid[0][c] != bg and all(grid[r][c] == grid[0][c] for r in range(h))), None)
    if divider_col is not None:
        divider = grid[0][divider_col]
        pts = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if c != divider_col and grid[r][c] != bg and grid[r][c] != divider]
        if not pts:
            return out
        left = min(c for r, c, v in pts)
        right = max(c for r, c, v in pts)
        for r, c, v in pts:
            out[r][c] = bg
        shift = divider_col + 1 - left
        for r, c, v in pts:
            out[r][c + shift] = v
        stripe_col = divider_col + 1 + (right - left) + 1
        if stripe_col < w:
            for r in range(h):
                out[r][stripe_col] = 8
    return out

